sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    try {
        var rm = new sn_ws.RESTMessageV2('Procurement API', 'create_order');
        rm.setStringParameterNoEscape('request_number', current.getValue('number'));
        rm.setStringParameterNoEscape('equipment', current.equipment.getDisplayValue());
        rm.setStringParameterNoEscape('quantity', current.getValue('quantity'));
        rm.setStringParameterNoEscape('requested_for', current.requested_for.getDisplayValue());
        rm.setHttpTimeout(10000);   // 10 s: never wait forever

        var response = rm.execute();
        var status = response.getStatusCode();

        if (status >= 200 && status < 300) {
            current.work_notes = 'Procurement order created (HTTP ' + status + ').';
        } else {
            current.work_notes = 'Procurement call failed (HTTP ' + status + '): ' + response.getBody();
            gs.error('[x_2228927_equipm_0] Procurement HTTP ' + status + ' for ' + current.getValue('number'));
        }
        current.setWorkflow(false);   // don't re-trigger business rules / flows from this bookkeeping update
        current.update();

    } catch (ex) {
        // Network error, bad endpoint, etc. Log it; a retry job could pick these up.
        gs.error('[x_2228927_equipm_0] Procurement call exception: ' + ex.message);
    }

})(current, previous);
